from pathlib import Path
import json,hashlib
OUT=Path(__file__).parent
COMMON=['All story and cast choices are provisional independent pilot options, not owner-selected canon.','Every panel is a new composition. Original anchors guide drawing and appeal, never a collage or reused final panel.','Adult principal cast only. No generated lettering: exact dialogue is editable gallery typography.','Quiet matte floors and grouped surfaces. Preserve medium-defining contour/brush/hatch marks.','One frozen instant per panel. Current-state field is authoritative; never import later damage into an earlier panel.']
def say(*pairs):return [{'speaker':p[0],'text':p[1]} for p in pairs]
def panel(i,action,state,camera,copy=None,zone='top-left',continuity=None):
 zones={'top-left':{'x':.04,'y':.035,'w':.43,'h':.21},'top-right':{'x':.53,'y':.035,'w':.43,'h':.21},'top-band':{'x':.04,'y':.025,'w':.92,'h':.19},'bottom-left':{'x':.04,'y':.77,'w':.45,'h':.19},'none':None}
 return {'id':i,'action':action,'current_state':state,'camera':camera,'copy':copy or [],'lettering_zone':zones[zone],'continuity_requirements':continuity or []}
def save(d):
 d['schema']='PilotChapterScript/1';d['status']='provisional-editorial-script';d['owner_approval']=None;d['editorial_rules']=COMMON
 d['reading_length_note']='Compact 16-panel pilot. Designed for roughly 3–5 minutes including art contemplation; actual reading speed varies. Not a claim of full serialized chapter length.'
 for b in d['beats']:
  b['power_limit']=d['power_rule']; assert len(b['copy'])<=2
  assert sum(len(c['text'].split()) for c in b['copy'])<=29
 assert len(d['beats'])==16 and len([b for b in d['beats'] if not b['copy']])>=3
 assert [b['id'] for b in d['beats']]==[d['id']+f'{i:02}' for i in range(1,17)]
 (OUT/(d['id']+'.json')).write_text(json.dumps(d,indent=2)+'\n')

NG={'id':'NG','title':'Nightglass Courier','chapter_title':'The Delivery Below','premise':'A courier seeking admission to the upper routes abandons his qualifying delivery when a glass ray attacks a suspended maintenance lift. His tiny one-line pulling skill saves a stranded worker and earns a dangerous address.','emotional_engine':'Aren wants his skill acknowledged by the city above; under pressure he chooses the work worth being known for, then resents the price rather than smiling away his ambition.','future_engine':'Deliveries into erased districts, rival couriers and glass fauna expose who controls the city routes. Progression comes from stronger anchors, load judgment and increasingly bold blade-assisted maneuvers.','style_contract':{'anchor':'01 Nightglass Courier original full image','medium':'Thin controlled anime contours, elegant facial planes, angular dark hair, tailored pale jacket against black clothing; luminous glass translucency against layered inhabited navy architecture.','retain':'The integrated invitation of face, creature, city and night atmosphere; inhabited balconies and quiet cyan windows.','avoid':'Bodybuilder armor, uniform low-angle full-body shots, wet reflective pavement, citywide speckle and a ray inserted behind every close-up.'},'cast':[{'id':'aren','name':'Aren Vale','age':28,'visual':'Light-skinned adult man, slim athletic build, narrow appealing face, gray eyes, swept midnight hair. Tailored ivory waist-length jacket WITH long sleeves over fitted black high-neck top, black slim trousers, plain boots and one red courier cord. Closer to original full Nightglass elegance; distinct provisional adaptation, not automatic original cast selection.','equipment':'One solid silver crescent-edge short sword, black straight hilt, cyan pommel ring; RIGHT hand always. Flat sealed cream dispatch wallet on belt.'},{'id':'sera','name':'Sera Voss','age':33,'visual':'Light-skinned square-faced woman, copper chin-length bob, burgundy tailored thighcoat, black trousers and boots. City route inspector, dry wit rather than antagonist.','equipment':'Simple black short spear carried upright when present; no use in this pilot.'},{'id':'pell','name':'Pell','age':54,'visual':'Light-skinned older man with short gray hair, stubble, mustard maintenance jacket and charcoal trousers, broad work harness.','equipment':'Harness attached to lift rail until transfer.'},{'id':'ray','name':'Glass ray','visual':'Single immense navy translucent glass-wing ray, broad crescent wings, cyan circular sensory lights, narrow central beak, one long tail. Living alien animal; no humanoid face.'}],'setting':'Layered vertical city at blue night. Upper admission gate on RIGHT, maintenance lift below LEFT side of same bridge, thick black metal anchor posts. Warm human windows, distant hanging gardens.','power_rule':'Tension Line: one thin cyan line from the RIGHT sword pommel to ONE visible metal anchor pulls Aren toward that anchor. It cannot push or lift the whole maintenance car. Carrying another adult visibly strains his grounded shoulder/stance.','beats':[
panel('NG01','Aren crosses a thin high bridge toward a small warm-lit upper-route gate; a distant ray arcs between inhabited towers.','Aren jacket intact; sword sheathed at right hip; dispatch wallet sealed; no line.','Extreme-wide high diagonal; Aren under 12% frame height, city layers dominant.',zone='none'),
panel('NG02','At the gate Sera indicates the lit delivery-intake booth far BEYOND the turnstile. Aren holds his sealed wallet; his smile is hopeful but guarded. Sera checks entry, not delivery completion.','Both on stable bridge; no creature nearby; no power or damage.','Intimate eye-level two-shot, chest-up.',say(('Sera','Intake is beyond the gate. Deliver before closing. Then we discuss upper routes.'),('Aren','I practiced looking unimpressed. How am I doing?'))),
panel('NG03','A glass beak clamps the maintenance lift’s suspension coupling below the bridge; one thick cable bends under its bite.','Lift remains attached but skewed; Pell inside, hands on rail; ray beak intact.','Tight mechanical/creature insert; beak, coupling and cable clearly separate.',zone='none'),
panel('NG04','Pell’s car hangs tilted below the walkway. Aren turns away from the gate toward his shout.','Single taut suspension cable holds lift; Pell still harnessed; Aren on bridge above.','Wide vertical geography: Aren upper right, car lower left, ray outside car.',say(('Pell','The brake is gone!'),('Sera','Aren. That gate will not wait.'))),
panel('NG05','Aren places the sealed dispatch wallet on Sera’s open palm and draws his crescent with the right hand.','Wallet transferred unopened to Sera; sword right hand; jacket intact; no line.','Close hands and Aren’s determined face; no ray or floor detail.',say(('Aren','Neither will he.'),('Sera','You understand what you are giving up?'))),
panel('NG06','Aren crouches at the bridge edge and attaches his pommel line to the heavy post behind his right shoulder.','One taut line from right sword pommel to visible post; both boots braced on bridge; lift below out of frame.','Low medium side, complete boots and both line endpoints.',say(('Aren','It pulls me. Not the whole car.'),('Aren','Try not to be a heavy man, Pell.'))),
panel('NG07','Aren descends onto the tilted lift roof, a taut line climbing from pommel to the bridge anchor above-right. Pell looks up through the open hatch.','Aren on roof, both boots spread; line holds him toward upper post; Pell harness still clipped. Jacket intact.','High oblique wide with clear upper anchor, lift and adult size contrast.',say(('Pell','I have been meaning to eat less.'),('Aren','Excellent. Start immediately.'))),
panel('NG08','The ray releases the coupling and turns its beak toward Aren on the roof; its immense wing blots out the upper city.','Cable still supports car; ray beak intact; Aren right sword between beak and hatch, left arm free.','Low extreme-wide threat scale, Aren under 18% frame height; one focal cyan eye.',zone='none'),
panel('NG09','Aren’s right crescent edge catches the lower side of the closing beak; his bent elbow and twisted torso absorb contact.','One blade/beak contact; left boot planted, right boot sliding; line taut to upper-right post; jacket hem snagged on roof lip and torn now.','Very close oblique contact with readable face, hand, hilt and beak; crop boots, hem and anchor deliberately. Adjacent wide frames establish those persistent states; no effect burst covering contact.',say(('Aren','Wrong delivery.'))),
panel('NG10','He leans away from the upper anchor; the taut pommel line pulls the hooked blade up-right, tipping the beak away from Pell’s hatch.','Right hand owns blade throughout; contact maintained; both boots braced, beak visibly deflected, jacket hem torn.','Wide side showing anchor-to-pommel line and blade-to-beak chain.',say(('Aren','Pell. Unclip. Now.'))),
panel('NG11','With the ray’s mouth deflected outside the roof, Pell climbs through the hatch and grips Aren’s free LEFT forearm.','Pell unclips the harness SAFETY TETHER from the lift rail; tether hangs in car but harness remains WORN around his body. Pell clear of hatch; right sword disengaged; line still to upper post.','Medium human contact; clasp and both shoulders unambiguous.',say(('Pell','Your arm—'),('Aren','Complain after we land.'))),
panel('NG12','The line pulls Aren and Pell diagonally up-right toward the bridge; empty lift drops lower-left when its cable finally parts.','Both people airborne together with one forearm clasp; right pommel tether taut to bridge post; empty lift separate below. Torn hem persists.','Extreme-wide vertical rescue, both humans small against city; clear three destinations.',zone='none'),
panel('NG13','Aren and Pell sprawl safely on the bridge, Sera gripping Pell’s harness shoulder; Aren’s sword rests in his right hand beside him.','Both rescued adults supported by dry deck; line slack; no new wounds. Gate visibly shut behind Sera.','Ground-level medium three-person aftermath with quiet surface.',say(('Pell','I owe you a delivery.'),('Aren','Make it one that counts.'))),
panel('NG14','Sera returns the unstamped sealed wallet. Aren stares at the closed gate over her shoulder.','Wallet remains unopened; jacket hem torn; right sword sheathed; no active power.','Close face and rejected wallet, city reduced to broad shapes.',say(('Sera','No stamp. I cannot change that.'),('Aren','I know. That does not make me less angry.'))),
panel('NG15','Pell offers a second small black envelope with a simple silver broken-circle seal. No generated address lettering is required; Pell identifies the addressee in dialogue.','Original wallet on belt; new black envelope intact in Pell’s hand. All safely on bridge.','Tactile close envelope and hands; enough quiet area for label and speech.',say(('Pell','This is addressed to you. From Lower District.'),('Aren','That district has been empty for twenty years.'))),
panel('NG16','Aren stands at a descending stair into the fog, black envelope in LEFT hand, right sword sheathed; far below, a dark doorway lights cyan.','Safe bridge behind; torn jacket hem retained; no active tether; new address opens a future route, no resolution claimed for city mystery.','Long rear three-quarter, Aren under 20% frame height; vast lower-city descent.',say(('Aren','Apparently someone forgot to stop writing.')),zone='top-right') ]}
save(NG)

BP={'id':'BP','title':'Black Petal','chapter_title':'A Voice That Knows Your Name','premise':'Ilyra follows her missing brother’s voice into a condemned glasshouse. Its beautiful predator repeats stolen speech; breaking the rooted bloom frees a trapped caretaker but destroys the comforting illusion she came for.','emotional_engine':'Hunger for reunion versus the courage to demand evidence. Ilyra can fight decisively yet remains vulnerable to one familiar sentence.','future_engine':'A trade in cultivated memories leads through haunted estates and impossible gardens. Each case offers a seductive version of a missing person, while Ilyra seeks what actually happened to her brother.','style_contract':{'anchor':'19 Black Petal original full image','medium':'Elegant softly modeled pale faces, fine controlled hair edges, desaturated portrait illustration, translucent broad charcoal petals with selective silver filigree.','retain':'Intimate beautiful unease and scale contrast between tailored human and floral horror.','avoid':'Anime conversion, armor clutter, all-over silver threads, dense moss grain, gore and generic haunted-house rubble.'},'cast':[{'id':'ilyra','name':'Ilyra Sen','age':30,'visual':'Pale adult woman, elegant oval face, gray eyes, smooth chin-length dark brown bob with ivory nape underlayer. Black split-tail coat, high white collar, dark pleated combat trousers, slim boots.','equipment':'One silver single-edge saber with open oval black guard in RIGHT hand; silver LEFT forearm guard. Small plain silver clasp at collar.'},{'id':'neris','name':'Neris','age':57,'visual':'Light-skinned older female caretaker, long angular nose, gray hair in low knot, plain charcoal dress, faded ivory shawl. Wary and practical.','equipment':'Plain iron door key on waist cord; no weapon.'},{'id':'bloom','name':'Mourning Bloom','visual':'Enormous translucent charcoal flower, empty oval center edged with sparse silver thorns, broad dark petals, ONE thick tapering root ending in a single thorn foot. No humanoid mask or hands.','equipment':'Heavy petals sweep like broad cutting leaves; root pins a door threshold.'}],'setting':'Abandoned curved-rib glasshouse in pale overcast mist. White entrance at LEFT, small caretaker room with a weight-jammed door at RIGHT; broad matte maroon ground, a few pale fallen petals.','power_rule':'The bloom can replay stolen voices only while its single thick root is planted; it must lift that root to turn its heavy face. Root exposed during a committed petal sweep. Ilyra has ordinary saber skill, no new aura.','beats':[
panel('BP01','Ilyra stands small before the immense glasshouse entrance; inside the mist, one soft dark flower silhouette hangs motionless.','Coat intact; saber sheathed; no exposed root or captive yet.','Extreme-wide frontal architecture, heroine under 10% height.',zone='none'),
panel('BP02','Ilyra stops with her hand on the entrance latch as a familiar voice comes from deep inside.','Face hopeful despite guarded posture; saber still sheathed.','Close profile and still hand, background nearly blank mist.',say(('Bloom / Oren’s voice','Little moth. Come inside.'),('Ilyra','Oren?'))),
panel('BP03','Inside, the bloom’s empty center faces Ilyra. Its thick root is planted across the base of the small room’s iron door.','Root intact and planted, door blocked; Ilyra by left entrance; coat intact.','Wide lateral geography, clear flower/root/blocked door.',say(('Ilyra','You promised never to call me that.'),('Bloom / Oren’s voice','Little moth. Come inside.'))),
panel('BP04','Behind the small door’s upper glass pane Neris pounds once; Ilyra notices her while keeping the flower in peripheral view.','Neris enclosed in room, both hands visible on glass; door pinned at bottom by root.','Medium over Ilyra’s shoulder, room glass and living face readable.',say(('Neris','Do not answer it.'),('Ilyra','A little late for that.'))),
panel('BP05','Ilyra draws her right-hand saber and slowly circles toward the room. The flower leans without turning its face; its planted root bows under its weight.','Saber right, left guard free; root still fixed at door base; coat intact.','High oblique, heroine left of rooted flower; clear intended flanking path.',say(('Neris','It borrowed my husband first.'),('Ilyra','Then it has had practice.'))),
panel('BP06','The bloom lifts its whole thorn foot to turn toward Ilyra. Neris pushes the room door a finger-width open as pressure releases.','Root visibly off threshold; flower’s empty center silent; room door only slightly open.','Low tight insert spanning root gap and door bottom.',zone='none'),
panel('BP07','The root stamps down onto the threshold again; a broad petal rises over Ilyra like a dark sail.','Room door pinned shut again; root planted; saber right low, left guard rising; coat intact.','Low wide threat, flower huge and heroine small but readable.',say(('Bloom / Oren’s voice','Little moth. Come inside.'),('Ilyra','Tell me what you called me after the fire.'))),
panel('BP08','Ilyra ducks a sweeping petal; its tip snags and tears the rear coat hem while her left guard protects her head.','First coat damage: one ragged rear hem tear. Saber in right hand kept outside body; petal passing behind neck, not through it. Root stays planted.','Close diagonal action, clear petal/coat contact and face.',say(('Bloom / Oren’s voice','Little moth. Come inside.'))),
panel('BP09','Crouched beside the committed root, Ilyra looks from the silent room door to the flower’s empty center.','Root intact and planted; petals facing old attack lane; torn rear hem visible. Right saber held low.','Intimate eye-level face with Neris faintly visible through distant glass.',say(('Ilyra','I came for a person.'),('Ilyra','You only brought me a voice.'))),
panel('BP10','She plants both boots and draws her right saber back along a clean lane toward the exposed root above its thorn foot.','Blade clearly short of root; left forearm guards ribs; root still intact, coat hem torn.','Ground-level medium setup, complete grip and blade-to-root gap.',zone='none'),
panel('BP11','A single right-handed cut passes through the thick root; the heavy flower tips away as a clear gap opens above the planted stump.','Root fully separated; the short stump is now LOOSE on the threshold because the heavy body no longer pins it down. Body tilts away from room; heroine on both boots, saber following through.','Wide side impact; bright mist gap separates both severed ends.',say(('Neris','Mind the head!'))),
panel('BP12','Ilyra pushes the loose, unweighted stump aside with her boot; Neris shoves the unjammed door outward as the flower slumps behind them.','Door moving outward; Neris stepping into glasshouse; severed body on floor, root stump displaced from hinge path. Torn hem persists.','Medium two-person practical effort; no triumphant pose.',say(('Ilyra','I was hoping it did not have one.'),('Neris','It has opinions. Those are worse.'))),
panel('BP13','Beside the collapsed oval center, a small folded paper packet has spilled from the severed root. Ilyra lifts it with her left guarded hand.','Saber lowered right; Neris safe by open room; bloom inert; packet damp but sealed with simple silver broken-leaf seal.','Tactile close hand and packet, sparse fallen petal shapes.',zone='none'),
panel('BP14','Neris recognizes the seal as Ilyra opens the packet; inside lies her brother’s plain dark coat button and a nursery delivery slip.','Button and slip in left palm; no claim of brother physically present. Right saber sheathed now.','Close two faces above one clearly legible prop area.',say(('Neris','The nursery sent that with yesterday’s planting.'),('Ilyra','This was on his coat when he vanished.'))),
panel('BP15','Ilyra folds the slip carefully, her expression steadier than at the entrance. Neris wraps her shawl around her shoulders.','Rescued caretaker safe; clue retained; torn coat hem unchanged; no active creature.','Quiet chest-up two-shot; pale glasshouse ribs grouped.',say(('Neris','Does that mean he is alive?'),('Ilyra','It means someone knows more than a flower.'))),
panel('BP16','Ilyra and Neris leave through the white entrance. Deep inside another sealed glasshouse bay a dark petal unfurls behind frosted glass.','Immediate predator down and room free; second bloom only distant silhouette, no new attack or invented brother body.','Extreme-wide rear departure, humans small; controlled dark shape at far right.',say(('Ilyra','We start with the nursery.')),zone='top-left') ]}
save(BP)

ST={'id':'ST','title':'Soft Thunder','chapter_title':'No Ticket for Thunder','premise':'Tavi tries to recover a caravan’s stolen signal bell from an enormous wind-breathing ram. A brief disastrous contest reveals that the ram wants relief from the painful clang, not treasure, and Tavi negotiates an unconventional ride.','emotional_engine':'A proud improviser wants to travel on her own terms. She learns what the opponent wants and turns a losing contest into a deal without becoming meek or giving up her ambition.','future_engine':'Tavi and a stubborn ram cross living weather-country, taking absurd jobs to reach the far skyports. Her grounded wind-pulse technique grows through timing, breath and using terrain creatively.','style_contract':{'anchor':'18 Soft Thunder original full image','medium':'Rounded expressive cartoon contours, large eyebrows and elastic mouths, opaque block-painted clouds and warm/cool color masses.','retain':'Muscular charm, broad orange/coral/turquoise palette, enormous creature personality and generous open sky.','avoid':'Airbrushed plastic, dense individually shaded wool curls, field speckle, fractured ground and particle storms.'},'cast':[{'id':'tavi','name':'Tavi Ember','age':27,'visual':'Athletic adult woman, broad expressive face, teal eyes, warm light complexion, short curly coral hair swept up with one forward tuft. Turquoise cropped vest over cream top, loose orange fighting trousers, red ankle wraps and cream boots.','equipment':'Rounded red gauntlets: anatomical RIGHT has cream circular pressure plate; anatomical LEFT cream crescent. No initial damage. Turquoise cloth padding strip tied around waist over a cream belt; whole strip can be untied and detached.'},{'id':'mara','name':'Mara','age':45,'visual':'Light-skinned stocky female caravan captain, silver braid, ochre poncho, dark trousers, stout boots, small blue neck scarf. Amused pragmatist.','equipment':'Plain rope halter and caravan tallybook; no weapon.'},{'id':'ram','name':'Gale Ram','visual':'Living blue cloud-wool ram twice human height, cream muzzle, orange cheeks, curled blue horns, four stout legs and one cloud tail. Broad grouped wool shapes; no armor.','equipment':'Plain brass caravan signal bell approximately human-head height, snagged by its strap on near horn; opening broad enough for bulky gauntlets.'}],'setting':'Cream chalk ridge above green windmill hills; wooden caravan platforms and bright cloth sails to LEFT, broad safe grass hollow to RIGHT. A low wooden fence divides paths, with one wide openable gate.','power_rule':'Stored Breath: Tavi charges one short wind pulse in her RIGHT circular gauntlet only while both boots are braced. Losing grounding dissipates any held charge. Release recoils her backward; she cannot recharge airborne. The LEFT crescent glove is defensive.','beats':[
panel('ST01','A distant sky-caravan lifts cloth sails above a chalk ridge while Tavi runs toward it; a huge blue ram stands in its path with a brass bell on its horn.','Both gloves intact and uncharged; Tavi on ridge; caravan stopped.','Extreme-wide sunny landscape, Tavi under 10% height; caravan and ram distinct.',zone='none'),
panel('ST02','Mara points to the bell while Tavi leans on the fence, pretending she is not out of breath.','Ram at distance; gate closed; gauntlets intact.','Friendly medium two-shot, quiet sky behind faces.',say(('Mara','Bring back my signal bell. I will find you a seat.'),('Tavi','A seat? I was negotiating a window.'))),
panel('ST03','Tavi holds out an open LEFT crescent glove toward the ram; its orange cheek bulges and the bell hangs beside its ear.','No charge or damage; ram four feet planted; heroine safely out of horn reach.','Low medium creature/human exchange.',say(('Tavi','You do not even have luggage. What do you need a bell for?'))),
panel('ST04','Tavi plants both boots and winds her RIGHT circular gauntlet beside her ribs, one small white compression disk forming.','Right charging, left crescent at chin; ram remains planted and wary.','Close low three-quarter including both boots and both glove symbols.',say(('Tavi','Both feet down. Then we can discuss it loudly.'))),
panel('ST05','The ram blows one broad wedge from its mouth; Tavi lifts backward off the chalk, eyes wide and knees bent.','Both heroine boots airborne, right disk gone; gloves intact; ram four feet planted.','Wide side action, visible mouth-source to torso-target wedge.',zone='none'),
panel('ST06','Tavi lands on her right boot and LEFT crescent palm, sliding across one broad chalk ribbon.','LEFT glove outer knuckle edge chips now; RIGHT glove intact at chest; no new charge. Ram remains distant and grounded.','Medium low landing with entire left shoulder/elbow/palm chain and right boot support inside frame.',say(('Tavi','Lost my footing. Lost my charge.'),('Tavi','That was a rude amount of discussion.'))),
panel('ST07','As the bell swings near its ear, the ram winces and clamps one floppy ear down with a horn tilt. Tavi notices from her crouch.','Ram not attacking; bell strap still hooked over horn; left glove chipped, right uncharged.','Intimate creature face/ear/bell insert, Tavi small at edge.',say(('Tavi','Oh. You hate the noise.'))),
panel('ST08','Tavi sits deliberately on the ground and fully unties the turquoise waist strip, holding the detached folded cloth in her left glove while the ram relaxes.','Gloves correctly sided; left chip retained; no charge; whole turquoise strip detached from waist; cream belt remains; no turquoise cloth tail attached to her.','Quiet wide profile with generous sky and distance between them.',zone='none'),
panel('ST09','She offers the cloth padding in an open hand; the ram lowers its head until the bell is within reach without charging her.','Heroine standing again, both boots grounded; bell still on horn; ram cooperative wary eyes.','Medium eye-level negotiation.',say(('Tavi','Your ears. My ride.'),('Tavi','Neither of us has to be miserable. Deal?'))),
panel('ST10','Tavi holds the large bell steady by its rim while pressing a broad fold of the detached cloth around its clapper. One simple loose knot is already in place. The ram watches suspiciously.','RIGHT circle hand holds rim; LEFT chipped crescent hand pads clapper; bell still attached to horn by strap.','Tactile close equipment/hands, clear bell opening and soft cloth.',zone='none'),
panel('ST11','With the padded bell now hanging from a fence peg, Tavi charges a tiny RIGHT pulse with both feet planted; ram waits beside her.','Bell off horn and on peg; padding tied around clapper; left glove chipped and guarding loosely; right charging.','Medium grounded demonstration with bell target well separated.',say(('Tavi','Small breath. Small sound.'),('Tavi','I can learn. Occasionally.'))),
panel('ST12','A short narrow puff from her RIGHT glove rocks the bell gently. The ram’s ears remain relaxed, eyes widening in approval.','Right pulse spent; both feet stay planted with slight backward lean; bell padded and moving, no explosion.','Close side source/action/target, enough room to see the ram reaction.',say(('Tavi','See? A civil conversation.'))),
panel('ST13','Mara holds the recovered padded bell while the ram crouches its four legs to offer Tavi its back.','Bell now returned to Mara; ram no longer carries it; gloves same damage; Tavi looking between mount and captain.','Wide comic reveal, whole ram crouch and caravan beyond.',say(('Mara','That is not one of our seats.'),('Tavi','It has a better window.'))),
panel('ST14','Tavi climbs onto the ram using a broad wool shoulder and its lowered back; Mara steadies her boot for one awkward second.','Four ram legs grounded; Tavi halfway seated, no levitation; bell with Mara out of frame.','Medium awkward physical comedy, no fighting effects.',say(('Tavi','Tell nobody about this part.'),('Mara','I will need more cloth for that bargain.'))),
panel('ST15','On the settled ram, Tavi and Mara exchange a brief handshake at comfortable height. The ram looks impatiently down the open gate.','Tavi seated securely; Mara grounded; gate open; no active power; left chip visible.','Warm close three-character expression composition.',say(('Mara','Follow us to the first skyport. Then choose your road.'),('Tavi','I like the sound of that. Quietly.'))),
panel('ST16','The caravan and ram travel along a high green ridge toward a floating storm-island; Tavi points eagerly while the ram looks back at her with comic doubt.','Partnership underway, immediate bell problem resolved; no new storm attack. Bell aboard caravan, gauntlets unchanged.','Extreme-wide departure, rider very small, vast route opening.',say(('Tavi','Next stop: somewhere with lunch.')),zone='top-left') ]}
save(ST)

RC={'id':'RC','title':'Red Current','chapter_title':'One Hit Owed','premise':'Ren enters a brutal bridge trial with borrowed gauntlets and wins access to the upper rings by returning a blade-shark’s own strike. His victory is real. So is the debt the weapon writes into his arm.','emotional_engine':'Brash ambition and rivalry: Ren refuses to remain a spectator and is willing to take a frightening shortcut. Winning validates his nerve while exposing the cost he dismissed.','future_engine':'Each higher arena reveals another lender of force. Ren must master what his gauntlets borrow, who collects it and whether victory can free him instead of binding him deeper. Vexa is a rival with reasons to understand that bargain.','style_contract':{'anchor':'13 Red Current original full image','medium':'Black and white directional pen hatching with bold silhouette blacks, athletic angular faces, red gauntlets and localized red impact accents.','retain':'Kinetic foreshortening, enormous geometric shark shapes, spiral bridge architecture, drawn muscle planes with selective hatch direction.','avoid':'Glossy gray CGI muscles, shiny vinyl trousers, omnipresent red auras, tiny floor lines and all-over shark swarms.'},'cast':[{'id':'ren','name':'Ren Varr','age':27,'visual':'Light-skinned adult man with angular grin, long black braid from shaved sides, strong athletic build. Sleeveless ivory zip vest with black hood lining, loose black combat trousers, tall black lace-up boots.','equipment':'Red armored gauntlets. RIGHT has one broad black central plate that lights red when loaded; LEFT has a plain smooth red back. No initial injury, no initial wrist mark.'},{'id':'vexa','name':'Vexa Rill','age':31,'visual':'Light-skinned athletic woman, sharp cheekbones, cropped black hair with one white forelock, sleeveless charcoal coat with white collar, black trousers and flat combat boots. Cool competitive gaze.','equipment':'Small iron upper-ring entry key on cord; folded spectator permit. She does not fight this pilot.'},{'id':'shark','name':'Blade-shark','visual':'One giant angular white shark-like aerial predator, black upper fins, dark mouth with large triangular teeth, small red eyes. Bold folded-paper planes and traceable tail/fins, not a collage of many fish.'}],'setting':'Vast looping white concrete bridges above a dark sea. Trial platform at lower ring, high spectator rail beyond. A broad dry circular landing zone, one black boundary stripe, no game HUD.','power_rule':'Borrowed Counter: the RIGHT black-plate gauntlet stores ONE directly blocked physical impact and releases it in ONE punch. It cannot stack charges. The spent arm goes numb and a red debt mark appears around that wrist; the cost is revealed only after the release.','beats':[
panel('RC01','Ren stands tiny on the lowest trial bridge while one huge blade-shark circles beyond the spiral ramps overhead.','Both gauntlets uncharged, wrist unmarked, clothing intact; Vexa at distant spectator rail.','Extreme-wide vertical scale, Ren under 10% height, one creature silhouette.',zone='none'),
panel('RC02','Vexa holds an upper-ring key between two fingers as Ren rolls his shoulders beneath her rail.','Key belongs to Vexa; Ren standing outside trial stripe, gloves intact and uncharged.','Medium rivalry two-shot, upper/lower social height clear.',say(('Vexa','Clear the bridge. Earn the key.'),('Ren','You make it sound as if nobody has tried.'))),
panel('RC03','Vexa catches sight of the black plate on Ren’s right gauntlet; his grin thins for a moment.','RIGHT plate dark; no wrist mark or pain; left glove plain red.','Close glove and two faces; no monster in frame.',say(('Vexa','Borrowed Counter? Did you read the terms?'),('Ren','I read the part where it hits back.'))),
panel('RC04','Ren crosses the black stripe alone. Above him the shark folds into a dive, beak and leading fin aligned toward his chest.','Ren boots planted; right bracer raised uncharged; left hand guards chin; shark intact.','Wide high oblique geometry showing attack lane and safe rail.',zone='none'),
panel('RC05','The shark’s heavy leading fin crashes against Ren’s raised RIGHT bracer. His forearm remains attached and elbow bends under the load.','Single fin/plate contact; right plate begins red load glow; left glove away from contact; no wrist debt mark yet.','Close oblique impact, fin surface visibly flattened against broad plate, no effect cloud hiding contact.',say(('Ren','Mine.'))),
panel('RC06','Ren is driven backward across the dry bridge on both boots; his right shoulder twists behind him while the red plate holds its stored charge.','Both boots scrape one broad skid; a rip begins at vest side seam now. Shark passes overhead instead of remaining at contact.','Low wide body consequence, clearly separated shark and fighter.',say(('Ren','That was considerably more than advertised.'))),
panel('RC07','On one knee, Ren inspects the loaded plate while Vexa leans over the rail with a terse warning.','RIGHT plate glows with one contained red core; LEFT glove braces knee; vest side seam torn, wrist still unmarked.','Intimate medium; charging hardware visible without UI.',say(('Vexa','One hit. Do not ask it for two.'),('Ren','I only need one good answer.'))),
panel('RC08','The shark makes a broad return arc beneath a huge bridge arch, turning its open mouth toward Ren’s small braced silhouette.','Stored right charge retained; no new contact; creature fully intact.','Extreme-wide side, predator path readable as one simple arc.',zone='none'),
panel('RC09','Ren sets his left foot forward, turns his right shoulder back and lowers his charged RIGHT fist beside his ribs, smiling into the approaching shadow.','Right loaded, left guard raised; both boots grounded; vest tear persists.','Medium low three-quarter, clear shoulder-to-elbow-to-fist chain.',say(('Ren','Come collect.'))),
panel('RC10','Ren rotates his hips and drives the RIGHT loaded fist upward into the shark’s lower angular jaw as it reaches him.','One physical fist/jaw contact; folded jaw plane visibly dents, right plate discharging; left glove at ribs. Both boots transmit force.','Very low close-wide impact; right forearm crosses torso toward target, complete hand ownership.',zone='none'),
panel('RC11','The discharged force throws the shark up and away from the trial bridge; its head tips, tail follows, and Ren finishes the punch below.','Right plate now dark/spent; shark displaced out of bridge lane with one bent lower-jaw plane; Ren boots grounded. No wrist close-up.','Wide diagonal consequence with large empty gap between fighter and creature.',say(('Vexa','Bridge clear.'))),
panel('RC12','Ren walks through the far side of the trial stripe as Vexa grudgingly hands him the upper-ring key.','Objective won; shark away in distance; right plate dark, vest torn; Ren receives key with LEFT hand.','Medium eye-level victory exchange.',say(('Ren','You could try sounding impressed.'),('Vexa','I am. That is why I am worried.'))),
panel('RC13','Alone for a beat, Ren tries to open his spent RIGHT hand. The fingers barely move; a thin red branching band emerges at the exposed wrist edge.','First visible debt mark begins on RIGHT wrist now; no mark on left; key securely held left.','Tactile close right wrist/hand, no generated words or numerical meter.',zone='none'),
panel('RC14','Ren turns the marked wrist toward Vexa, forcing a grin that does not quite hold.','Right hand numb, red wrist band visible; left holds earned key; both safe on upper exit.','Close two faces and wrist, keep mark clear.',say(('Ren','Temporary?'),('Vexa','The numbness. The debt has other ideas.'))),
panel('RC15','Vexa points down past the spiraling bridge while Ren looks over the rail; a vast dark angular shape begins to turn beneath the sea.','No new attack; earned key retained; right wrist marked, plate spent. Creature lender only distant silhouette.','High wide viewpoint from two small adults into deep water.',say(('Vexa','Those gauntlets did not invent that force.'),('Ren','Then I should probably meet the owner.'))),
panel('RC16','Ren steps onto the ascending stair, marked right arm hanging stiff, upper-ring key in his left. Below, one enormous red eye opens in the dark sea.','Victory and cost both persist; nobody rescued or sacrificed; future confrontation unresolved.','Long rear three-quarter with stair ascent and distant eye separated.',say(('Ren','After I use the key.')),zone='top-left') ]}
save(RC)

FL={'id':'FL','title':'Floodline Detective','chapter_title':'The Coat That Walked Home','premise':'A flood investigator is asked to explain why a missing man’s coat returned without him. A brief still-water memory and an impossible dry footprint lead to a canal predator carrying its victim, and a deliberately opened sluice.','emotional_engine':'Corin hides his responsibility behind wit and skepticism. He starts by treating a witness as mistaken, corrects himself when evidence contradicts him, and earns trust by solving the immediate danger.','future_engine':'Each flooded district contains a supernatural crime with a physical tell. Corin follows whoever routes living predators through municipal infrastructure while his own past in the flood authority complicates every case.','style_contract':{'anchor':'06 Floodline Detective original full image','medium':'Strong black brush masses, scraped white edges and controlled grayscale planes, limited hot-magenta institutional lights. Graphic ink narrative with selective rough marks.','retain':'Adult face character, monumental flood infrastructure, black umbrella-segment creature and dry wit under genuine threat.','avoid':'Glossy leather everywhere, repetitive white water sparkles, polished wet mirror floor, decorative ink splatter over clues.'},'cast':[{'id':'corin','name':'Corin Vey','age':38,'visual':'Light-skinned adult man, lean strong build, angular tired face, short black hair with gray temple, faint stubble. Off-white long coat over charcoal high-neck shirt and belted black combat trousers; flat black boots.','equipment':'One long straight iron ward-pole with a broad simple solid C-shaped head: upper shoulder can prop an upper jaw while lower curve catches lower lip. No moving mechanism. Held in both hands when fighting. Small plain black notebook kept inside coat.'},{'id':'ada','name':'Ada Marr','age':29,'visual':'Light-skinned adult woman with short blunt blond hair, blunt expressive face, dark hooded rain cape over gray knit top, pale practical trousers and black boots. Direct, angry sister.','equipment':'Her missing brother’s dark work coat folded over one arm.'},{'id':'lio','name':'Lio Marr','age':32,'visual':'Light-skinned adult man, short dark hair, narrow face, pale rolled-sleeve work shirt, dark trousers, plain boots. Unconscious when first physically seen, then breathing and shaken.','equipment':'Small brass municipal sluice key on a cord at neck.'},{'id':'eel','name':'Umbrella eel','visual':'One thick black segmented canal creature with overlapping umbrella-like membrane ribs, tapering body and broad hinged pale mouth. Two large readable gripping jaws, no human limbs.','equipment':'Its wet body moves through connected water; it cannot propel its full weight across the dry high ledge.'}],'clue_note':'The coat came back means Ada found the discarded wet coat by this ledge and brought it to Corin; it is not a literal walking coat. FL09 reveals how the carried victim left an isolated wet footprint. The still-water imprint and matching key establish a sluice opening, but who ordered it remains a series mystery.','setting':'Monumental concrete floodworks. Dry elevated inspection ledge on LEFT, black canal two meters below RIGHT; one broad spillway gap and a tall locked sluice with a magenta signal panel. Water uses large black/white shape groups.','power_rule':'Stillwater Witness: touching an undisturbed pool with two bare fingertips shows ONE brief visual imprint of the last person it reflected. Any ripple erases the imprint. It does not identify motives or predict events. The creature’s dry-ledge limitation is observed physical behavior, not a second detective power.','beats':[
panel('FL01','Corin waits on a dry inspection ledge beneath colossal flood arches. Ada approaches carrying a soaked dark coat above black canal water.','All people dry-footed on elevated ledge; no creature visible; Corin hook pole upright.','Extreme-wide architectural noir, two people under 12% height, one magenta panel.',zone='none'),
panel('FL02','Ada drops the coat onto Corin’s notebook. He looks up at her without moving the pole from his other hand.','Coat wet, notebook shut beneath it; Ada angry, Corin unimpressed; no power.','Close human two-shot with concrete broad shadows.',say(('Ada','My brother’s coat came back. He did not.'),('Corin','Coats are poor witnesses. Let us find a better one.'))),
panel('FL03','Ada points to a single wet footprint on the otherwise dry high ledge, well away from the nearest ladder. Corin crouches to inspect its sharply stopping heel.','One footprint, not a trail; water below separate; coat on ledge beside Ada.','Tactile ground insert with fingertip scale; broad dry slab, no other texture noise.',say(('Ada','He never used the ladder.'),('Corin','You said that. I should have listened.'))),
panel('FL04','Corin notices a sheltered, perfectly still water pocket inside a concrete recess beside the footprint. He removes one glove.','Pole laid safely on ledge; LEFT hand bare, pool still; no imprint yet; Ada standing behind.','Medium crouched discovery, small sheltered pool and black canal clearly distinct.',say(('Corin','Do not move the water.'),('Ada','I was not planning to.'))),
panel('FL05','Two bare LEFT fingertips touch the edge of the still pocket; within it appears one faint image of Lio reaching toward an open sluice wheel.','Single memory imprint confined to water pocket, not a full ghost in the scene; no present-day Lio body yet.','Close overhead evidence, hand and reflected past figure both readable.',zone='none'),
panel('FL06','A vibration rings the water pocket and breaks the imprint into one broad ripple; Corin catches Ada’s elbow to stop her stepping closer.','Memory fully gone; right hand on Ada elbow, left bare hand withdrawing; pole still on ledge.','Medium sharp reaction, faces and erased pool visible.',say(('Ada','What did you see?'),('Corin','Your brother opened something. Something noticed.'))),
panel('FL07','A huge black umbrella-ribbed shape rises from the canal, its mouth level with the ledge; Corin reaches for his pole.','Creature entirely connected to canal; dry ledge intact; Ada behind Corin, coat abandoned safely.','Low wide threat scale with clear vertical height between canal and dry platform.',zone='none'),
panel('FL08','The eel snaps at Corin’s boot but its wet body stalls against the vertical dry wall. Corin steps back instead of lunging forward.','Mouth crosses ledge lip but trunk remains in water; Corin both boots dry-grounded; pole gripped two-handed.','Close side mouth/boot gap, actual ledge geometry visible.',say(('Corin','You can reach.'),('Corin','You cannot climb. Good distinction.'))),
panel('FL09','Through the open mouth Ada sees Lio’s pale sleeve and limp hand behind a membrane fold. His one wet boot heel brushes the dry ledge, reproducing the isolated footprint. She grips Corin’s coat sleeve.','Lio physically present for first time, airway near open mouth; creature not biting through his body. Corin pole poised.','Medium human sightline toward pale sleeve inside dark mouth; no gore.',say(('Ada','Lio! That was his footprint.'),('Corin','Stay here. I have already been wrong once today.'))),
panel('FL10','Corin seats the broad C-shaped pole head at the near corner of the creature’s mouth. Its lower curve catches the lower lip and its upper shoulder braces the upper jaw, leaving the far half of the mouth clear for Lio. Both hands grip separated shaft positions.','Two countercontacts on one solid C-head: lower curve under lower lip, upper shoulder against upper jaw. No victim contact; straight shaft outside the far-side exit lane; Corin boots dry-grounded.','Close three-quarter implement construction and safe victim clearance.',zone='none'),
panel('FL11','He leans back with the ward-pole and brings the lower jaw onto the dry ledge lip. The C-head’s upper shoulder physically props the upper jaw while its lower curve retains the lower lip; the far side remains an open exit. The heavy trunk slides against the wall below.','Pole acts as a physical two-contact jaw prop, both hand grips maintained. Lower jaw rests on concrete edge; C-head upper shoulder holds upper jaw away. Trunk in water; Lio sleeve visible through unobstructed far-side exit.','Wide side full force chain: boots, torso, pole, jaw, ledge and water.',say(('Corin','Ada. Take his shoulders.'),('Ada','Then keep that mouth open.'))),
panel('FL12','Ada hauls Lio through the clear far side of the mouth by his upper shirt and shoulders while Corin maintains both C-head contacts, mechanically holding the jaws apart.','Lio chest and head fully outside far side of mouth, legs following. Corin braced, C-head upper/lower countercontacts retained at near corner; shaft remains outside rescue path; no extra limbs or severing.','High medium rescue with distinct adults, hands and creature mouth.',say(('Corin','This is my persuasive face.'))),
panel('FL13','Corin releases the hook after Lio’s boots clear the lip. The eel drops back into the canal, sending one broad black splash below the dry platform.','All three adults safely dry-ledged; creature retreating into water; pole free and held by Corin.','Wide release and clear safety separation.',zone='none'),
panel('FL14','Lio coughs while Ada supports him sitting against the wall. Corin notices the brass key hanging at Lio’s throat.','Lio alive and conscious, wet clothes; Ada holding shoulders; no creature attack; key visible.','Intimate three-person aftermath, no dramatic water effects.',say(('Lio','They told me the sluice was empty.'),('Corin','Who is they?'))),
panel('FL15','Lio gives the municipal key to Corin’s bare left palm. Its plain triangular head matches the large sluice lock in the background.','Key transferred to Corin; Ada and Lio safe; no lettering required on key; notebook inside coat again.','Tactile clue with matching lock silhouette beyond.',say(('Lio','Flood Authority. Night shift.'),('Corin','Of course. They used to pay me to call this weather.'))),
panel('FL16','Corin stands before the towering locked sluice, the small key in his left hand and pole right; Ada guides Lio away along the safe ledge.','Immediate missing-person case resolved; deliberate routing remains open. All injuries limited to Lio exhaustion, no new wounds.','Extreme-wide rear, human tiny under institution and one hot-magenta light.',say(('Corin','Now I send them an invoice.')),zone='top-left') ]}
save(FL)

